insert into plans.element_def (code, ord, title, owner_role, guidance, sections) values
 ('1', 1, 'Signature Page', 'agency_admin', 'Names, qualifications and signatures of the preparer, technical reviewer and agency administrator. The complexity rating and minimum burn boss qualification come from Element 3.', '[{"key": "admin_unit", "label": "Administrative unit(s)"}, {"key": "burn_name", "label": "Prescribed fire name"}, {"key": "ignition_unit", "label": "Prescribed fire unit (ignition unit)"}, {"key": "complexity", "label": "Complexity rating"}, {"key": "min_rxb", "label": "Minimum burn boss qualification"}, {"key": "notes", "label": "Notes"}]'::jsonb),
 ('2A', 2, 'Agency Administrator Ignition Authorization', 'agency_admin', 'Completed before each ignition period. Discussion items A–H, the FMO/burn boss recommendation and authorized ignition dates.', '[{"key": "changes", "label": "A. Changes since approval"}, {"key": "compliance", "label": "B. Compliance"}, {"key": "conditions", "label": "C. Ability to meet plan conditions"}, {"key": "notifications", "label": "D. Notifications"}, {"key": "briefing", "label": "E. Staff briefing"}, {"key": "circumstances", "label": "F. Circumstances that could affect implementation"}, {"key": "contingency_expect", "label": "G. Contingency notification expectations"}, {"key": "wildfire_expect", "label": "H. Wildfire declaration expectations"}, {"key": "recommendation", "label": "FMO / RXB implementation recommendation"}, {"key": "dates", "label": "Authorized ignition dates"}]'::jsonb),
 ('2B', 3, 'Prescribed Fire Go/No-Go Checklist', 'burn_boss', 'Answered by the burn boss on each burn day. The answers are recorded on the burn day record; this element holds any unit-specific items.', '[{"key": "preliminary", "label": "Preliminary questions (changed conditions, amendments)"}, {"key": "items", "label": "Unit-specific go/no-go items"}, {"key": "test_fire", "label": "Test fire decision"}]'::jsonb),
 ('3', 4, 'Complexity Analysis Summary and Final Complexity', 'planner', 'Summary and Final Complexity Worksheet (PMS 424-1), signed.', '[{"key": "summary", "label": "Complexity summary"}, {"key": "final", "label": "Final complexity rating and rationale"}]'::jsonb),
 ('4', 5, 'Description of Prescribed Fire Area', 'planner', 'Physical description, fuels, values and the maps. Much of this is filled from the database overlay.', '[{"key": "physical", "label": "A. Physical description (location, size, topography, project area, ignition units)"}, {"key": "fuels", "label": "B. Vegetation / fuels (on-site, adjacent, % by type, fuel models)"}, {"key": "values", "label": "C. Unique features, natural resources and values"}, {"key": "maps", "label": "D. Maps"}]'::jsonb),
 ('5', 6, 'Objectives', 'planner', 'Measurable resource objectives and prescribed fire objectives.', '[{"key": "resource", "label": "Resource objectives"}, {"key": "fire", "label": "Prescribed fire objectives"}]'::jsonb),
 ('6', 7, 'Funding', 'planner', 'Cost and funding source.', '[{"key": "cost", "label": "Cost"}, {"key": "source", "label": "Funding source"}]'::jsonb),
 ('7', 8, 'Prescription', 'planner', 'How the fire behaviour will meet the objectives, the environmental and fire behaviour parameters, and the modelling documentation.', '[{"key": "narrative", "label": "A. Prescription narrative"}, {"key": "parameters", "label": "B. Prescription parameters (also in the Prescription tab)"}, {"key": "modeling", "label": "Fire behaviour modelling / empirical documentation"}]'::jsonb),
 ('8', 9, 'Scheduling', 'planner', 'Ignition time frames or season, projected duration, constraints (MBCA nesting period, training schedule).', '[{"key": "schedule", "label": "Implementation schedule"}, {"key": "duration", "label": "Projected duration"}, {"key": "constraints", "label": "Constraints"}]'::jsonb),
 ('9', 10, 'Pre-burn Considerations and Weather', 'planner', 'On-site and off-site preparation, how and how often weather and smoke forecasts are obtained, notifications.', '[{"key": "onsite", "label": "On-site considerations"}, {"key": "offsite", "label": "Off-site considerations"}, {"key": "weather", "label": "Weather and smoke forecasts: method and frequency"}, {"key": "notifications", "label": "Notifications"}]'::jsonb),
 ('10', 11, 'Briefing', 'burn_boss', 'Briefing checklist.', '[{"key": "checklist", "label": "Briefing checklist and notes"}]'::jsonb),
 ('11', 12, 'Organization and Equipment', 'burn_boss', 'Positions (PMS 310-1 qualifications), equipment and supplies.', '[{"key": "positions", "label": "Positions"}, {"key": "equipment", "label": "Equipment"}, {"key": "supplies", "label": "Supplies"}]'::jsonb),
 ('12', 13, 'Communication', 'burn_boss', 'Command, tactical and air radio frequencies, telephone numbers.', '[{"key": "radio", "label": "Radio frequencies"}, {"key": "phones", "label": "Telephone numbers"}]'::jsonb),
 ('13', 14, 'Public and Personnel Safety, Medical', 'burn_boss', 'Hazards and mitigations (including UXO), emergency medical procedures, evacuation, facilities.', '[{"key": "hazards", "label": "Safety hazards and mitigation"}, {"key": "medical", "label": "Emergency medical procedures"}, {"key": "evacuation", "label": "Evacuation methods"}, {"key": "facilities", "label": "Emergency facilities"}]'::jsonb),
 ('14', 15, 'Test Fire', 'burn_boss', 'Planned location, on-site weather and results (results are recorded on the burn day).', '[{"key": "location", "label": "Planned location"}, {"key": "procedure", "label": "Procedure and acceptance criteria"}]'::jsonb),
 ('15', 16, 'Ignition Plan', 'burn_boss', 'Firing methods, sequences and patterns, devices, minimum ignition staffing. Variants by wind direction are in the Variants tab.', '[{"key": "methods", "label": "Firing methods (techniques, sequence, patterns)"}, {"key": "devices", "label": "Devices"}, {"key": "staffing", "label": "Minimum ignition staffing"}]'::jsonb),
 ('16', 17, 'Holding Plan', 'burn_boss', 'General holding procedures, critical holding points and actions, minimum holding organization.', '[{"key": "procedures", "label": "General procedures"}, {"key": "critical_points", "label": "Critical holding points and actions"}, {"key": "minimum", "label": "Minimum organization or capabilities"}]'::jsonb),
 ('17', 18, 'Contingency Plan', 'burn_boss', 'Management action points (MAPs), actions, minimum contingency resources and maximum response times. Trigger points are drawn on the map.', '[{"key": "maps_points", "label": "Management action points"}, {"key": "actions", "label": "Actions needed"}, {"key": "resources", "label": "Minimum contingency resources and maximum response times"}]'::jsonb),
 ('18', 19, 'Wildfire Declaration', 'burn_boss', 'Who declares, IC assignment, notifications, extended attack actions.', '[{"key": "who", "label": "Who declares"}, {"key": "ic", "label": "IC assignment"}, {"key": "notifications", "label": "Notifications"}, {"key": "extended", "label": "Extended attack actions"}]'::jsonb),
 ('19', 20, 'Smoke Management and Air Quality', 'planner', 'Compliance, permits, smoke-sensitive receptors (from the database), impacted areas, mitigation.', '[{"key": "compliance", "label": "Compliance and permits"}, {"key": "receptors", "label": "Smoke-sensitive receptors"}, {"key": "impacts", "label": "Potentially impacted areas"}, {"key": "mitigation", "label": "Mitigation strategies"}]'::jsonb),
 ('20', 21, 'Monitoring', 'planner', 'Fuels, forecast and observed weather, fire behaviour, objective monitoring and smoke dispersal: how, when and by whom.', '[{"key": "fuels", "label": "Fuels information"}, {"key": "weather", "label": "Forecast and observed weather"}, {"key": "behaviour", "label": "Fire behaviour"}, {"key": "objectives", "label": "Monitoring to confirm objectives"}, {"key": "smoke", "label": "Smoke dispersal"}]'::jsonb),
